    if all(len(set(row)) <= 1 for row in grid):
        vals = [row[0] for row in grid]
        for period in range(1, h + 1):
            motif = {}
            ok = True
            for r, v in enumerate(vals):
                if v == 0:
                    continue
                k = r % period
                if k in motif and motif[k] != v:
                    ok = False
                    break
                motif[k] = v
            if ok:
                # Use the shortest compatible period; unseen motif slots are
                # inferred from adjacent observed bands when possible.
                if all(k in motif for k in range(period)):
                    return [[motif[r % period]] * w for r in range(h)]
                # Continue only if this period has a unique color inference.
                # (For ARC examples, use neighboring known motif slots.)
                for k in range(period):
                    if k not in motif:
                        left = next((motif[(k-d) % period] for d in range(1, period+1) if (k-d) % period in motif), None)
                        right = next((motif[(k+d) % period] for d in range(1, period+1) if (k+d) % period in motif), None)
                        if left is not None and left == right:
                            motif[k] = left
                if all(k in motif for k in range(period)):
                    return [[motif[r % period]] * w for r in range(h)]
        return [row[:] for row in grid]

    # Diagonal stripes with wraparound. Determine whether colors are constant
    # on r-c or r+c residue classes, then extend the motif around the grid.
    candidates = []
    for sign in (-1, 1):
        motif = {}
        ok = True
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v == 0:
                    continue
                key = (r + sign*c) % h
                if key in motif and motif[key] != v:
                    ok = False
                    break
                motif[key] = v
            if not ok:
                break
        if ok:
            candidates.append((len(motif), sign, motif))
    if candidates:
        _, sign, motif = max(candidates)
        # Fill any unseen residue from the closest known residue cyclically.
        for k in range(h):
            if k not in motif:
                for d in range(1, h + 1):
                    if (k-d) % h in motif:
                        motif[k] = motif[(k-d) % h]
                        break
        return [[motif[(r + sign*c) % h] for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
